export const retailers = [...new Set(catalog.map(p=>p.retailer))];
export function filterMatches(scores, {budget, category, retailer='all'}) {
 if(!Number.isFinite(budget)||budget<10||budget>20000) return [];
 const best=Math.max(0,...scores.map(s=>s.score));
 return scores.filter(s=>Number.isFinite(s.score)&&s.score>=best*.18).map(s=>({product:catalog.find(p=>p.caption===s.label),score:s.score})).filter(s=>s.product&&s.product.price<=budget&&(category==='all'||s.product.category===category)&&(retailer==='all'||s.product.retailer===retailer)).sort((a,b)=>b.score-a.score).slice(0,6);
}
